"""Generated by checks/country_rules.py from the system's T005 / BNKA and the customer's
reference lists (official postal codes, SWIFT BIC directory)."""

import pandas as pd

from checks.base import BaseCheck, Evaluation, is_blank
from checks.country_rules import place_key, violates

_BIC = r"[A-Z]{4}[A-Z]{2}[A-Z0-9]{2}(?:[A-Z0-9]{3})?"  # malformed BICs are AP087's


class CountryFormatCheck(BaseCheck):
    check_class = "country_format_check"

    def columns(self) -> list[str]:
        cols = [self.rule["field"], self.rule["country_field"]]
        return cols + [self.rule[k] for k in ("street_field", "postcode_field") if self.rule.get(k)]

    def evaluate(self, df: pd.DataFrame) -> Evaluation:
        r = self.rule
        value = df[r["field"]].astype("string").str.strip().fillna("")
        country = df[r["country_field"]].astype("string").str.strip().fillna("")
        if r["family"] == "format":
            specs = {c: (int(s[0]), str(s[1])) for c, s in r["specs"].items()}
            population = value.ne("") & country.isin(specs.keys())
            failing = pd.Series([population.at[i] and violates(value.at[i], *specs[country.at[i]])
                                 for i in df.index], index=df.index, dtype=bool)
            return Evaluation(population, failing, {"country_rules": "T005"}, invalid_values_field=r["field"])
        if r["family"] == "required":
            street = ~is_blank(df[r["street_field"]])
            population = country.isin(r["countries"]) & street
            return Evaluation(population, value.eq(""), {"countries_requiring_postal_code": len(r["countries"])})
        keys = set(r["keys"])
        if r["family"] == "place":  # city / region against the postal code's entries in REF_POSTAL
            pair = pd.Series([place_key(c, p) for c, p in zip(country, df[r["postcode_field"]].astype("string")
                                                                .fillna(""))], index=df.index)
            full = pd.Series([place_key(p, v) for p, v in zip(pair, value)], index=df.index)
            population = value.ne("") & pair.isin(set(r["scope"]))
            return Evaluation(population, ~full.isin(keys), {"reference": "REF_POSTAL"},
                              invalid_values_field=r["field"])
        if r["family"] == "bic":  # BIC8 is the head office: BIC11 with branch 'XXX'
            bic = value.str.upper()
            bic11 = bic.where(bic.str.len() != 8, bic + "XXX")
            population = bic.str.fullmatch(_BIC) & bic.str.slice(4, 6).isin(r["countries"])
            return Evaluation(population, ~bic11.isin(keys), {"reference": "REF_BIC"},
                              invalid_values_field=r["field"])
        population = value.ne("") & country.isin(r["countries"])
        return Evaluation(population, ~(country + "|" + value.str.upper()).isin(keys),
                          {"reference": r.get("reference", "BNKA")}, invalid_values_field=r["field"])
